const cap=(x,a,b)=>Math.max(a,Math.min(b,x)),ok=msg=>({ok:true,msg}),no=msg=>({ok:false,msg});
function rand(s){s.seed=(Math.imul(s.seed,1664525)+1013904223)>>>0;return s.seed/4294967296;}
export function initExpanded(g){const s=g.expanded??={version:1,seed:145017,realms:{},history:[],lastTick:-1};for(const r of Object.keys(g.politics.realms))s.realms[r]??={active:null,last:{},decisions:{},lastDecision:-12,lastEvent:-12};return s;}
const ruler=(g,r)=>g.politics.people[g.politics.realms[r]?.ruler];
const controlled=(g,r,p)=>p?.owner===r&&(!g.campaignWar?.occupations[p.id]||g.campaignWar.occupations[p.id].by===r);
const sorted=(list,fn)=>list.slice().sort((a,b)=>fn(a)-fn(b)||a.id.localeCompare(b.id));
const relationKey=(a,b)=>[a,b].sort().join('|');
function opinionPair(t){return [t.bond==='match'?t.person:t.actor,t.partner??t.person];}
